insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0601$t$, $t$Bridgeton$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Property Compliance (CPC)$t$, $j$["Issued by: Department of Housing, Code Enforcement & Rent Leveling (Code Enforcement Office)","Contact: Danielle Deitz, Housing Supervisor · 856-455-3230 Ext. 223 · DeitzD@cityofbridgeton.com","How to apply: Fill out the Application for Certificate of Property Compliance (check 'Seller' and 'SALE APPLICATION', give the buyer and agent details) and file it with the Code Enforcement Office, City Hall, 181 E Commerce Street, Bridgeton, NJ 08302. Call 856-455-3230 (Housing Supervisor ext. 223, Housing Office Clerk ext. 217) to confirm the fee and schedule the inspection.","Inspection under the 2015 International Property Maintenance Code (the City's checklist is a general guide, not a full list)","Clean yard, grass and weeds under 10 inches, no rat infestation, sound accessory structures","House number at least 4 inches high","Sound foundation, walls, roof, gutters, chimney, porches, stairs and decks","Windows and doors in good repair and weather tight; screens from April 15 to October 15","Interior surfaces sanitary with no peeling or loose paint or plaster; railings and guards where required","Working plumbing with no leaks; water heater installed right with relief valve and discharge pipe","Heat of at least 65 degrees from October 1 to May 15; fuel-burning appliances vented outside","At least 60 amp electric service, 2 outlets per habitable room, GFCI outlet in bathroom and laundry, cover plates on all outlets","Exit doors and windows openable from inside without keys (no double-keyed deadbolts)","One fire extinguisher within 10 feet of the kitchen (on the 2021 checklist)","Smoke detectors on every level, in every bedroom and in the hall outside sleeping areas; CO detectors within 10 feet of all bedrooms"]$j$::jsonb, $j$[{"label":"Certificate of Property Compliance, first inspection (fee listed on the Housing page for the Certificate of Property Compliance; the page does not say whether it covers sale CPCs as well as rental CPCs)","amount":"$35"},{"label":"Certificate of Property Compliance, each re-inspection (same note as above)","amount":"$18"}]$j$::jsonb, $t$https://www.cityofbridgetonnj.gov/DocumentCenter/View/996/Certificate-of-Property-Compliance-Application-PDF$t$, $t$https://www.cityofbridgetonnj.gov/187/Housing-Code-Enforcement-Rent-Leveling$t$, $j$[{"url":"https://www.cityofbridgetonnj.gov/187/Housing-Code-Enforcement-Rent-Leveling","label":"Official source (cityofbridgetonnj.gov)"},{"url":"https://www.cityofbridgetonnj.gov/DocumentCenter/View/996/Certificate-of-Property-Compliance-Application-PDF","label":"Official source (cityofbridgetonnj.gov)"},{"url":"https://www.cityofbridgetonnj.gov/DocumentCenter/View/214/Inspection-Checklist-2022-PDF","label":"Official source (cityofbridgetonnj.gov)"}]$j$::jsonb, $t$Resale Certificates Upon the sale of any property within the City of Bridgeton, a resale CPC needs to be filled out and filed with the Code Enforcement Office.$t$, $t$fe028a6ca1c6bf86c2bcc6985285b194132b7baed9e16a14919a9d4950fd3788$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":21,"q_ok":21,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0601.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0601.json$t$, true),
  ($t$0601$t$, $t$Bridgeton$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department · 856-451-0091 · justicej@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement.","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page, picking Bridgeton City as the municipality. Payment is due at the time of the inspection by check or money order payable to the City of Bridgeton Fire Department (the form says an online payment link will be on the invoice). Re-inspection for a failed or no-show inspection costs the same as the first inspection. The certificate is emailed to the address given and is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 / 856-451-0091.","Fire official in the NJ state directory, updated 1/12/2026: Jack Justice, Jr. · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","If there is a fire alarm system, a report from the alarm company is required (per the online application form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://docs.google.com/forms/d/e/1FAIpQLSd9PvQCoB-cH5v1UqIaPvFMeDzejV1zzNEnuFMw0yH7LAaFng/viewform","label":"Official source (docs.google.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"http://www.bridgetonfire.com/department","label":"Official source (bridgetonfire.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City of Bridgeton Fire Department is the local enforcing agency who is responsible for the enforcement of the Uniform Fire Safety Act within the City of Bridgeton, Hopewell Township, Greenwich Township, Stow Creek Township, Shiloh Borough, Fairfield Township, Downe Township, and Alloway Township.$t$, $t$ccfe33af39908acc108a952121b56279be7f0682b1358ee56043cd26d9a131e2$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":21,"q_ok":21,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0601.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0601.json$t$, true),
  ($t$0602$t$, $t$Commercial Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO)$t$, $j$["Issued by: Construction / Code Enforcement Office (Housing and Zoning Officer)","Contact: William White, Construction Official, Housing and Zoning Officer (also Plumbing Inspector) · 856-785-3100, ext. 320","How to apply: Call the Construction Office at 856-785-3100 ext. 320 to set up the inspection. Fill out the Application for Continued Certificate of Occupancy (block and lot, owner, seller's agent and buyer's agent) and pay at the time of application by cash, check or money order payable to 'Commercial Township'. Township offices are at 1768 Main Street, Port Norris.","Handrails on stairs with 3 or more risers; guardrails on porches or decks 30 inches or higher","No broken windows or doors; all must work","Switch plates and outlet covers in place; light fixtures with shades and no bare wires","No holes in walls or other structural damage; no exterior damage or roof leaks","Smoke detector on every level, within 10 feet of bedroom doors and in every bedroom","Carbon monoxide detector in the hallway within 10 feet of bedroom doors","Mounted ABC fire extinguisher within 10 feet of the kitchen (2017 list)","Breaker panel wired with no missing breakers","Hot and cold running water, working toilet, working heater; water heater relief valve extension 2 to 6 inches from the floor","4-inch white post 3 feet tall by the driveway with 3-inch reflective house numbers on two sides","No trash, motor vehicles or debris in the yard; all utilities on at the time of inspection","Bathroom window or exhaust fan; GFCI outlets within 3 feet of sinks","No flaking paint or stains on interior finishes; no double-keyed deadbolts","Water certificate from the Cumberland County Health Department and a septic certification","Also: Water certificate: A Water Certificate from the Cumberland County Health Department is required for the CO.","Also: Septic certification: Listed as item 23 on the 2017 CCO requirements."]$j$::jsonb, $j$[{"label":"Continued Certificate of Occupancy inspection, resale","amount":"$75"},{"label":"Re-inspection","amount":"$40.00"}]$j$::jsonb, $t$https://web.archive.org/web/20250418135548id_/https://commercialtwp.com/wp-content/uploads/2016/02/CCO-3-20-17.pdf$t$, $t$https://web.archive.org/web/20250321045909/https://commercialtwp.com/government/departments/housing/$t$, $j$[{"url":"https://web.archive.org/web/20250321045909/https://commercialtwp.com/government/departments/housing/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20250418135548id_/https://commercialtwp.com/wp-content/uploads/2016/02/CCO-3-20-17.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260401042214/https://www.commercialtwp.com/contact-us","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20250614110704/https://commercialtwp.com/government/departments/construction/","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$When are they required? When any property is sold When there is a change in tenants How do I get a C.O.? Contact the Construction Office at 856-785-3100, ext. 320 There is a $75 fee, $40.00 reinspection fee$t$, $t$221317c9a70a13840cc64a6d6af20305124a0a74cf687d2efc64162e53200837$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":8,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0602.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0602.json$t$, true),
  ($t$0602$t$, $t$Commercial Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Issuer not confirmed (NJ DCA Division of Fire Safety is the fire enforcing agency but marks Commercial Township smoke-certificate exempt)","Contact: Louis Kilmer, Bureau Chief, Bureau of Fire Code Enforcement · 609-633-6106","How to apply: Not confirmed. The DCA's online smoke certificate portal filters out towns marked smoke-certificate exempt, and Commercial Township is marked exempt. Ask the Township Construction Office (856-785-3100, ext. 320) whether the CCO inspection serves as the smoke/CO certificate, or ask the DCA Bureau of Fire Code Enforcement (609-633-6106).","Fire official in the NJ state directory (NJ DCA, state), updated 4/4/2025: Louis Kilmer · (609)633-6132","The Township's CCO checklist (2017) checks smoke detectors on every level, within 10 feet of bedroom doors and in every bedroom, a CO detector within 10 feet of bedroom doors, and a mounted ABC fire extinguisher within 10 feet of the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/offices/bfce.shtml","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20250418135548id_/https://commercialtwp.com/wp-content/uploads/2016/02/CCO-3-20-17.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$S Commercial Township$t$, $t$f28923d5f1f797c2032aa35865f0e340c9d51d301fec5f1eb5ed25b2cadf0dfd$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":8,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0602.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0602.json$t$, true),
  ($t$0604$t$, $t$Downe Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (CO) for resale$t$, $j$["Issued by: Zoning Office (Zoning Officer)","Contact: Nicole Marlette, Zoning Officer · 856-447-3100 Ext. 103 · zoningdowne@comcast.net","Apply: Submit everything before the inspection can be scheduled; inspections are only on Thursdays, 9 AM to 12 PM. Do not schedule settlement until all items are submitted and approved.","How to apply: Before the inspection is scheduled, send to Downe Township, Attn: Zoning, 288 Main Street, Newport NJ 08345: (1) a septic certificate or septic waiver in the buyers' name, (2) a water certificate (Fortescue properties with public water are exempt), both from the Cumberland County Health Department, 309 Buck Street, Millville (856-327-7602), (3) the fire certificate from the City of Bridgeton Fire Department, (4) a $25 check payable to Downe Township and (5) the Certificate of Occupancy Application. The Zoning Office then calls to schedule the Thursday morning inspection. Buyers cannot move in until the CO is approved.","Handrails on stairs with 2 or more steps","Hot water relief valve extension 6 inches from the floor; appliances vented properly","Emergency exit if there is sleeping on a 3rd floor","Windows, screens, and interior and exterior doors in good condition","Working heating system, plumbing and water pressure; GFCI outlets near water","Ceilings, walls, floors and interior and exterior paint in good condition; sound roof","Exterior entrance lighting","Extermination, general clean up inside and out, and a garbage container","House number on the front of the house and a white 911 numbering post by the street (6 ft 4x4 post, 4 ft above ground, black numbers at least 4 inches or 3 inches if reflective, on both sides, near the driveway)","Also: Septic certificate or septic waiver: From the Cumberland County Health Department, in the buyers' name, before the CO inspection is scheduled (Ordinance 2021-10 accepts the County waiver).","Also: Water certificate: From the Cumberland County Health Department; Fortescue properties on public water are exempt.","Also: 911 numbering post: White 911 numbering post by the street per Ordinance 2024-06 is checked at the CO inspection."]$j$::jsonb, $j$[{"label":"CO inspection fee (check payable to Downe Township)","amount":"$25"},{"label":"CO re-inspection fee, if needed","amount":"$25"}]$j$::jsonb, $t$https://downetwpnj.org/wp-content/uploads/2026/07/CO-Inspection-Information-_-Application-Resale-_-LT-Rentals.pdf$t$, $t$https://downetwpnj.org/departments/zoning-office/$t$, $j$[{"url":"https://downetwpnj.org/wp-content/uploads/2026/07/CO-Inspection-Information-_-Application-Resale-_-LT-Rentals.pdf","label":"Official source (downetwpnj.org)"},{"url":"https://downetwpnj.org/","label":"Official source (downetwpnj.org)"},{"url":"https://downetwpnj.org/departments/zoning-office/","label":"Official source (downetwpnj.org)"}]$j$::jsonb, $t$Effective as of: Jan. 1, 2026 RE: CO INSPECTION - PROCESS & SCHEDULING REQUIRMENTS$t$, $t$9c572a10e98d4e7b616bb0dfcbef177855257299486065da4d3a3c8df4df679c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":25,"q_ok":24,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0604.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0604.json$t$, true),
  ($t$0604$t$, $t$Downe Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department · 856-451-0091 · justicej@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement.","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page, picking Downe Township as the municipality. Payment is due at the time of the inspection by check or money order payable to the City of Bridgeton Fire Department (the form says an online payment link will be on the invoice). Re-inspection for a failed or no-show inspection costs the same as the first inspection. The certificate is emailed to the address given and is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 / 856-451-0091.","Fire official in the NJ state directory, updated 5/18/2026: Jack Justice, Jr · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","If there is a fire alarm system, a report from the alarm company is required (per the online application form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://docs.google.com/forms/d/e/1FAIpQLSd9PvQCoB-cH5v1UqIaPvFMeDzejV1zzNEnuFMw0yH7LAaFng/viewform","label":"Official source (docs.google.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://downetwpnj.org/wp-content/uploads/docs/mayor/ordinances/2025/Ordinance-No_-2025-14-Fire-Prevention-Ordinance.pdf","label":"Official source (downetwpnj.org)"},{"url":"https://downetwpnj.org/wp-content/uploads/2026/07/CO-Inspection-Information-_-Application-Resale-_-LT-Rentals.pdf","label":"Official source (downetwpnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City of Bridgeton Fire Department is the local enforcing agency who is responsible for the enforcement of the Uniform Fire Safety Act within the City of Bridgeton, Hopewell Township, Greenwich Township, Stow Creek Township, Shiloh Borough, Fairfield Township, Downe Township, and Alloway Township.$t$, $t$08aa3f9b3457cf7894b69ce85d8985d18ae276204bd0a003453987365e5d0465$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":25,"q_ok":24,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0604.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0604.json$t$, true),
  ($t$0605$t$, $t$Fairfield Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (Sales Inspection / Sales Registration)$t$, $j$["Issued by: Zoning Office / Housing (Code Enforcement / Housing Inspector)","Contact: Mark Benjamin, Code Enforcement / Housing Inspector · 856-451-9284 (ext. 309) · MarkB@fairfieldtownshipnj.org","Apply: The fee list warns there is a minimum waiting period to get a C/O on a previously owned home; the length is not stated.","How to apply: Fill out the Fairfield Township Sales Inspection Form (owner, real estate agent, new owner's name, house / apartment / trailer, number of bedrooms) and pay the $75 sales registration fee to the Zoning Office, 70 Fairton Gouldtown Road, Bridgeton (mail: P.O. Box 240, Fairton, NJ 08320). Water and septic certifications are checked. To schedule or for questions call 856-451-9284 (the form says ext. 304, 8:30 AM to 12:30 PM, Monday to Friday).","Smoke detectors present and working","Carbon monoxide detectors present and working","Fire extinguisher mounted (on the 2023 form)","Water certification and sewer (septic) certification","Heating certification","Windows open, lock and have sound glass; doors in good condition","Plumbing pipes and fixtures, water pressure, water heater relief valve with floor discharge","Appliance venting and exhaust fans","Handrails and a 911 numbering pole","Emergency exit from a 3rd floor","Interior surfaces and interior and exterior paint; basement and firewalls; roof and chimney; porches, decks, stairs and railings","No mice, rats or roaches; clean property with a trash container","Electric wiring, outlets and GFCI outlets","Repairs found at inspection must be done within 30 days","Also: Water and septic certifications: The sales inspection form checks water certification and sewer certification; the form's back page records water and septic certifications received.","Also: Heating certification: Listed as item 21 on the sales inspection form."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy (sales form)","amount":"$75.00"},{"label":"Transfer of Ownership (listed separately on the same fee list; the page does not explain how it relates to the sales CCO)","amount":"$75.00"},{"label":"Sales registration fee, includes 1 initial inspection and 1 re-inspection","amount":"$75"},{"label":"Additional inspection after a failed re-inspection","amount":"$75"}]$j$::jsonb, $t$http://fairfieldtownshipnj.org/wp-content/uploads/2023/06/20230622124137835-2.pdf$t$, $t$http://fairfieldtownshipnj.org/departments/construction/rental-registration/$t$, $j$[{"url":"http://fairfieldtownshipnj.org/departments/construction/printed-material-fee-list/","label":"Official source (fairfieldtownshipnj.org)"},{"url":"http://fairfieldtownshipnj.org/departments/construction/rental-registration/","label":"Official source (fairfieldtownshipnj.org)"},{"url":"http://fairfieldtownshipnj.org/wp-content/uploads/2023/06/20230622124137835-2.pdf","label":"Official source (fairfieldtownshipnj.org)"},{"url":"http://fairfieldtownshipnj.org/wp-content/uploads/2022/11/NewSales23.pdf","label":"Official source (fairfieldtownshipnj.org)"},{"url":"http://fairfieldtownshipnj.org/about-fairfield/township-directory/","label":"Official source (fairfieldtownshipnj.org)"}]$j$::jsonb, $t$Transfer of Ownership $75.00 Certificate of Occupancy ( Click for RENTAL form ) $75.00 Certificate of Continued Occupancy ( Click for SALES form ) $75.00 Change of Occupancy $75.00$t$, $t$de0a024cba307482b472a0d2253f76e9d011299bb3d2741f6b533dd68cd88623$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":5,"fee_bad":0,"fee_unchecked":2,"quotes":24,"q_ok":21,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0605.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0605.json$t$, true),
  ($t$0605$t$, $t$Fairfield Township$t$, $t$CUMBERLAND$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bridgeton Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: Jack Justice Jr., Fire Official and Chief of Department · 856-451-0091 · justicej@cityofbridgeton.com","Apply: Submit the request 2 to 3 weeks before settlement; the lowest fee applies when the request is received 10 or more business days before settlement.","How to apply: Fill out the online 'CO and Smoke Certification Application' (Google Form) linked from the Bridgeton Fire Department's Uniform Fire Code page, picking Fairfield Township as the municipality. Payment is due at the time of the inspection by check or money order payable to the City of Bridgeton Fire Department (the form says an online payment link will be on the invoice). Re-inspection for a failed or no-show inspection costs the same as the first inspection. The certificate is emailed to the address given and is valid for 90 days. Questions: firedepartment@cityofbridgeton.com or 856-451-0090 / 856-451-0091.","Fire official in the NJ state directory, updated 7/25/2024: Jack Justice, Jr. · (856) 451-0091 · firedepartment@cityofbridgeton.com","Smoke alarms (UL listed) on every level; battery-only alarms must be the 10-year sealed battery type, and hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell, on the ceiling (not between joists)","A 10-year sealed smoke alarm in every bedroom","Smoke alarms and CO alarms must be less than 10 years old and working","Carbon monoxide alarm in the hallway within 10 feet of all bedrooms","House numbers at least 4 inches high, contrasting color, permanently fixed and visible from the street","Homes with solar panels, a backup generator or battery storage need a permanent printed 'Caution: Multiple Sources of Power' label at the main electrical panel and the electric meter","If there is a fire alarm system, a report from the alarm company is required (per the online application form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, 1-2 family, request received 10 or more business days before settlement","amount":"$45.00"},{"label":"Smoke/CO certificate, 1-2 family, request received 7 business days before settlement (source wording)","amount":"$90.00"},{"label":"Smoke/CO certificate, 1-2 family, request received fewer than 4 business days before settlement","amount":"$161.00"}]$j$::jsonb, $t$https://forms.gle/oWLh33S1kuggYuRQ8$t$, $t$http://www.bridgetonfire.com/uniform-fire-code$t$, $j$[{"url":"http://www.bridgetonfire.com/uniform-fire-code","label":"Official source (bridgetonfire.com)"},{"url":"https://static1.squarespace.com/static/51cc4632e4b06e55251db119/t/691f23865714647f5f7c666a/1763648390990/Occupancy+%26+Smoke+Certificates.pdf","label":"Official source (static1.squarespace.com)"},{"url":"https://docs.google.com/forms/d/e/1FAIpQLSd9PvQCoB-cH5v1UqIaPvFMeDzejV1zzNEnuFMw0yH7LAaFng/viewform","label":"Official source (docs.google.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"http://fairfieldtownshipnj.org/departments/bureau-of-fire-protection/","label":"Official source (fairfieldtownshipnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The City of Bridgeton Fire Department is the local enforcing agency who is responsible for the enforcement of the Uniform Fire Safety Act within the City of Bridgeton, Hopewell Township, Greenwich Township, Stow Creek Township, Shiloh Borough, Fairfield Township, Downe Township, and Alloway Township.$t$, $t$f10e21bd67b6f946b1123f44195179042421c1a0d81337f38734ad4da53e8675$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":5,"fee_bad":0,"fee_unchecked":2,"quotes":24,"q_ok":21,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0605.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0605.json$t$, true),
  ($t$0606$t$, $t$Greenwich Township$t$, $t$CUMBERLAND$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (housing inspection)$t$, $j$["Issued by: Office of Housing & Zoning (Zoning / Code Enforcement Officer)","Contact: Neal Sheppard, Zoning / Code Enforcement Officer · (856) 455-8640 · zoning@historicgreenwichnj.org","How to apply: Fill out the Township's Application for Continued Certificate of Occupancy (owner, seller's agent, buyer's agent, owner's future address) and pay at the time of application by cash, check or money order payable to Greenwich Township. The Township building is not regularly staffed; mail to Greenwich Township, P.O. Box 64, Greenwich, NJ 08323, or contact the Zoning / Code Enforcement Officer. The fee amounts are blank on the posted form.","Remove trash and debris inside and out; cut high grass and weeds; no standing water","Walkways, steps and driveways free of tripping hazards; accessory structures sound","Pools clean with self-closing, self-latching gates","No more than one unregistered vehicle","Sound siding, roof, flashing, gutters, foundation, chimney and structural members; exterior wood and metal protected and painted","House and unit numbers visible from the street","Handrails on stairs with more than 4 risers; guardrails at least 30 inches high","Windows open and stay open, with screens and unbroken glass; exterior doors open from inside without a key","Interior surfaces free of peeling paint; privacy locks on bedroom and bathroom doors; bathroom window or exhaust fan; dryer vented outside","Plumbing, water heater (110 degrees, discharge pipe about 6 inches from the floor) and heating system in safe working order","Carbon monoxide detector outside the bedroom areas","Two outlets per habitable room; GFCI outlets within 6 feet of water, in bathrooms, laundry and outdoors","Proof of extermination if insects or rodents are found; wood stoves inspected by a licensed chimney inspector","Work done without permits must be permitted and finaled","Passing County Health Department water test and septic certification (or waiver), and a passing fire inspection report from the Bridgeton Fire Department","Also: Water test and septic certification: Passing water test certification and septic certification or waiver from the Cumberland County Health Department are required for the housing inspection.","Also: Open permits: Work done without permits must get permits and final inspections from the Construction Office.","Also: Historic district: Homes in the historic district must meet Greenwich Historic Preservation Commission requirements."]$j$::jsonb, $j$[]$j$::jsonb, $t$http://www.historicgreenwichnj.org/wp-content/uploads/2022/05/CO.pdf$t$, $t$https://www.historicgreenwichnj.org/planning-documents/$t$, $j$[{"url":"https://www.historicgreenwichnj.org/planning-documents/","label":"Official source (historicgreenwichnj.org)"},{"url":"http://www.historicgreenwichnj.org/wp-content/uploads/2022/05/CO.pdf","label":"Official source (historicgreenwichnj.org)"},{"url":"http://www.historicgreenwichnj.org/wp-content/uploads/2025/12/Common-Violations.pdf","label":"Official source (historicgreenwichnj.org)"},{"url":"https://www.historicgreenwichnj.org/municipal-directory/","label":"Official source (historicgreenwichnj.org)"}]$j$::jsonb, $t$General Planning Documents, Ordinances, and Forms Certificate of Occupancy Application Certificate of Occupancy Application Common Housing Violations Common Violations$t$, $t$4bdf6d965d8d84bc76b7d1f072b31c1560eabaff4a2c852f948ae018870ac9c3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-10-01","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":24,"q_ok":22,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0606.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-10-01. Source: property/data/municipal-requirements/checked/0606.json$t$, true),
